char * cJSON_PrintIssue(const struct Issue * x) {
    char * s = NULL;
    if (NULL != x) {
        cJSON * j = cJSON_CreateIssue(x);
        if (NULL != j) {
            s = cJSON_Print(j);
            cJSON_Delete(j);
        }
    }
    return s;
}

void cJSON_DeleteIssue(struct Issue * x) {
    if (NULL != x) {
        if (NULL != x->assignees) {
            cJSON * x1 = list_get_head(x->assignees);
            while (NULL != x1) {
                cJSON_Delete(x1);
                x1 = list_get_next(x->assignees);
            }
            list_release(x->assignees);
        }
        if (NULL != x->body) {
            cJSON_free(x->body);
        }
        if (NULL != x->closed_at) {
            cJSON_free(x->closed_at);
        }
        if (NULL != x->comments_url) {
            cJSON_free(x->comments_url);
        }
        if (NULL != x->created_at) {
            cJSON_free(x->created_at);
        }
        if (NULL != x->events_url) {
            cJSON_free(x->events_url);
        }
        if (NULL != x->html_url) {
            cJSON_free(x->html_url);
        }
        if (NULL != x->labels) {
            struct Label * x1 = list_get_head(x->labels);
            while (NULL != x1) {
                cJSON_DeleteLabel(x1);
                x1 = list_get_next(x->labels);
            }
            list_release(x->labels);
        }
        if (NULL != x->labels_url) {
            cJSON_free(x->labels_url);
        }
        if (NULL != x->milestone) {
            cJSON_DeleteMilestone(x->milestone);
        }
        if (NULL != x->pull_request) {
            cJSON_DeleteIssuePullRequest(x->pull_request);
        }
        if (NULL != x->repository_url) {
            cJSON_free(x->repository_url);
        }
        if (NULL != x->state) {
            cJSON_free(x->state);
        }
        if (NULL != x->title) {
            cJSON_free(x->title);
        }
        if (NULL != x->updated_at) {
            cJSON_free(x->updated_at);
        }
        if (NULL != x->url) {
            cJSON_free(x->url);
        }
        if (NULL != x->user) {
            cJSON_DeleteUser(x->user);
        }
        cJSON_free(x);
    }
}

